WITH flattened_attrs AS (SELECT id, service, host, latency_ms, payload_json, context['trace'] AS trace, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, COALESCE(context['version'], 'unknown') AS version_or_default FROM app_logs WHERE latency_ms <> 1721) SELECT CASE WHEN latency_ms >= 1859 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, MAX(latency_ms) AS max_latency_ms, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, MIN(latency_ms) AS min_latency_ms, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN service = 'search' THEN 1 END), 0), 2) AS latency_ms_per_search, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN service = 'billing' THEN 1 END), 0), 2) AS latency_ms_per_billing FROM flattened_attrs GROUP BY CASE WHEN latency_ms >= 1859 THEN 'HIGH' ELSE 'LOW' END HAVING MIN(latency_ms) >= 0 ORDER BY min_latency_ms
